inc_or_decl:
// FireModeNum is not read by this body (the decompile takes only the pawn).
// flag byte at +0x522 &= 0xAF: clears mask 0x50 (bPrimaryInputQueued and the queued-fire bit)
bPrimaryInputQueued = false;
bFireQueued = false;
bool bBlocked = CanFireNow(true, false);   // virtual slot 0xd08 (unnamed)
if (!bBlocked && Weapon != nullptr) {
    if (IsWeaponUsable()) {   // virtual slot 0x6b0 (unnamed)
        Weapon->StopFire();   // virtual slot 0x6d8 on the weapon (unnamed)
    }
}
